#[test]
fn test_hash_form_equals_its_reference_and_tells_pictures_apart() {
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let a: &crate::port::Bitmap = &crate::port::bitmap_new(17, 9, 3);
    let b: &crate::port::Bitmap = &crate::port::bitmap_new(17, 9, 3);
    let t: &crate::port::Bitmap = &crate::port::bitmap_new(9, 17, 3);
    let o1: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let o2: &mut crate::port::Cells = &mut crate::port::Cells::new();
    sm_seed(st, 14);
    nt_fill(a, st);
    crate::port::cells_grow(o1, 4, 0);
    crate::port::cells_grow(o2, 4, 0);
    crate::port::bitmap_hash(a, o1, 1);
    nm_ref_hash(a, o2, 1);
    crate::testport::assert_eq(crate::port::cells_at(o1, 1), crate::port::cells_at(o2, 1), "high halves");
    crate::testport::assert_eq(crate::port::cells_at(o1, 2), crate::port::cells_at(o2, 2), "low halves");
    crate::testport::assert_eq(crate::port::cells_at(o1, 0), 0, "cells outside the pair are untouched");
    crate::testport::assert_eq(crate::port::cells_at(o1, 3), 0, "and after it");
    nm_ref_quarter(a, b, 0);
    crate::port::bitmap_set_u8(b, 16, 8, 2, crate::port::bitmap_u8(b, 16, 8, 2) + 1);
    crate::port::bitmap_hash(b, o2, 1);
    crate::testport::assert_that(crate::port::cells_at(o1, 2) != crate::port::cells_at(o2, 2), "one byte changed, a different hash");
    crate::port::bitmap_quarter_into(a, t, 1);
    crate::port::bitmap_hash(t, o2, 1);
    crate::testport::assert_that(crate::port::cells_at(o1, 2) != crate::port::cells_at(o2, 2), "a turned picture, a different hash");
}
