#[test]
fn test_a_page_of_three_inks_separates_into_three_layers_by_size() {
    let b: &crate::port::Bitmap = &crate::port::bitmap_new(100, 80, 3);
    let ws: &mut crate::port::Cells = &mut crate::port::Cells::new();
    nt_page_3(b);
    nm_ws_init(ws);
    crate::port::bitmap_hist_rgb(b, ws, nm_ws_hist());
    crate::testport::assert_eq(nt_layers(b, ws), 3, "paper and three inks: three layers");
    crate::testport::assert_eq(nm_layer_count(ws), 3, "the count is kept");
    crate::testport::assert_eq(nm_layer_get(ws, 0, 0), 800, "layer 1 is the light grey block, the largest");
    crate::testport::assert_eq(nm_layer_get(ws, 1, 0), 620, "layer 2 is black and holds its anti-aliased edge: 600 + 20");
    crate::testport::assert_eq(nm_layer_get(ws, 2, 0), 400, "layer 3 is the blue block");
    crate::testport::assert_eq(nm_paper_gray(ws), 255, "the paper bin is white");
    crate::testport::assert_eq(nm_layer_get(ws, 0, 8), ir_light(), "light grey: low chroma, lightness over ink-light");
    crate::testport::assert_eq(nm_layer_get(ws, 1, 8), ir_body(), "black: the body");
    crate::testport::assert_eq(nm_layer_get(ws, 2, 8), ir_color(), "blue: colour");
    crate::testport::assert_eq(nm_layer_get(ws, 2, 4), 17, "blue's mean red is its bin centre, 1 * 17");
}
