pub(crate) fn ras_sauvola_whole(g: &crate::port::Bitmap, mut isum: &mut crate::port::Cells, mut isq: &mut crate::port::Cells, mut sq: &mut crate::port::Cells, m: &crate::port::Bitmap) -> i32 {
    ras_integral(g, isum, isq);
    return ras_sauvola(g, isum, isq, sq, m);
}
pub(crate) fn nt_sauv_case(g: &crate::port::Bitmap, mut sq: &mut crate::port::Cells) -> i32 {
    // 1 when the banded form (r = 15, k = 87) equals the whole-page ras-sauvola, mask and ink count.
    let a: &crate::port::Bitmap = &crate::port::bitmap_new(crate::port::bitmap_w(g), crate::port::bitmap_h(g), 1);
    let b: &crate::port::Bitmap = &crate::port::bitmap_new(crate::port::bitmap_w(g), crate::port::bitmap_h(g), 1);
    let isum: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let isq: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let sv: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let n1: i32 = ras_sauvola_whole(g, isum, isq, sq, a);
    let n2: i32 = nm_sauvola(g, b, 15, 87, sv);
    if n1 != n2 {
        return 0;
    }
    return nt_same(a, b);
}
#[test]
fn test_banded_sauvola_equals_the_whole_page_form_on_three_pages() {
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let sq: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let a: &crate::port::Bitmap = &crate::port::bitmap_new(70, 50, 1);
    let b: &crate::port::Bitmap = &crate::port::bitmap_new(90, 64, 1);
    let c: &crate::port::Bitmap = &crate::port::bitmap_new(33, 21, 1);
    let mut x: i32 = 0;
    let mut y: i32 = 0;
    sm_seed(st, 21);
    ras_sqrt_table(sq);
    nt_fill(a, st);
    crate::testport::assert_eq(nt_sauv_case(a, sq), 1, "random noise, 70x50");
    y = 0;
    while y < 64 {
        x = 0;
        while x < 90 {
            if (y % 8) < 3 {
                crate::port::bitmap_set_u8(b, x, y, 0, 30 + sm_below(st, 40));
            } else {
                crate::port::bitmap_set_u8(b, x, y, 0, 200 + sm_below(st, 50));
            }
            x += 1;
        }
        y += 1;
    }
    crate::testport::assert_eq(nt_sauv_case(b, sq), 1, "text-like stripes with noise, 90x64");
    y = 0;
    while y < 21 {
        x = 0;
        while x < 33 {
            crate::port::bitmap_set_u8(c, x, y, 0, ((x * 7) + (y * 3)) % 256);
            x += 1;
        }
        y += 1;
    }
    crate::testport::assert_eq(nt_sauv_case(c, sq), 1, "a gradient narrower and shorter than the window, 33x21");
}
pub(crate) fn nt_sauv_brute(g: &crate::port::Bitmap, m: &crate::port::Bitmap, r: i32, k: i32, sq: &mut crate::port::Cells) -> i32 {
    // Sauvola by the definition: every window summed directly (no integral image).
    let w: i32 = crate::port::bitmap_w(g);
    let h: i32 = crate::port::bitmap_h(g);
    let mut x: i32 = 0;
    let mut y: i32 = 0;
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut x0: i32 = 0;
    let mut x1: i32 = 0;
    let mut y0: i32 = 0;
    let mut y1: i32 = 0;
    let mut n: i32 = 0;
    let mut s: i32 = 0;
    let mut q: i32 = 0;
    let mut v: i32 = 0;
    let mut mean: i32 = 0;
    let mut vr: i32 = 0;
    let mut thr: i32 = 0;
    let mut ink: i32 = 0;
    while y < h {
        x = 0;
        while x < w {
            x0 = x - r;
            if x0 < 0 {
                x0 = 0;
            }
            x1 = (x + r) + 1;
            if x1 > w {
                x1 = w;
            }
            y0 = y - r;
            if y0 < 0 {
                y0 = 0;
            }
            y1 = (y + r) + 1;
            if y1 > h {
                y1 = h;
            }
            s = 0;
            q = 0;
            j = y0;
            while j < y1 {
                i = x0;
                while i < x1 {
                    v = crate::port::bitmap_u8(g, i, j, 0);
                    s += v;
                    q += v * v;
                    i += 1;
                }
                j += 1;
            }
            n = (x1 - x0) * (y1 - y0);
            mean = s / n;
            vr = (q / n) - (mean * mean);
            thr = mean + (((((mean as i64) * (k as i64)) * (((2 * crate::port::cells_at(sq, vr)) - 256) as i64)) / 65536) as i32);
            if crate::port::bitmap_u8(g, x, y, 0) < thr {
                crate::port::bitmap_set_u8(m, x, y, 0, 255);
                ink += 1;
            } else {
                crate::port::bitmap_set_u8(m, x, y, 0, 0);
            }
            x += 1;
        }
        y += 1;
    }
    return ink;
}
#[test]
fn test_banded_sauvola_equals_the_definition_at_other_radii() {
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let sq: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let sv: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let g: &crate::port::Bitmap = &crate::port::bitmap_new(41, 29, 1);
    let a: &crate::port::Bitmap = &crate::port::bitmap_new(41, 29, 1);
    let b: &crate::port::Bitmap = &crate::port::bitmap_new(41, 29, 1);
    sm_seed(st, 22);
    crate::port::cells_grow(sq, 65536, 0);
    nm_sqrt_table(sq);
    nt_fill(g, st);
    crate::testport::assert_eq(nm_sauvola(g, a, 3, 87, sv), nt_sauv_brute(g, b, 3, 87, sq), "r = 3: the ink counts");
    crate::testport::assert_eq(nt_same(a, b), 1, "r = 3: the masks");
    crate::testport::assert_eq(nm_sauvola(g, a, 1, 60, sv), nt_sauv_brute(g, b, 1, 60, sq), "r = 1, k = 60: the ink counts");
    crate::testport::assert_eq(nt_same(a, b), 1, "r = 1: the masks");
    crate::testport::assert_eq(nm_sauvola(g, a, 40, 87, sv), nt_sauv_brute(g, b, 40, 87, sq), "a window wider than the page");
    crate::testport::assert_eq(nt_same(a, b), 1, "the masks");
}
