pub(crate) fn nt_text_lines(b: &crate::port::Bitmap, cdeg: i32, ink: i32) -> i32 {
    // Eight lines of ten two-part words (14 rows tall, a 4 px gap in each), the lines rising to the right by `cdeg`,
    // drawn in `ink` on a 1000 x 700 page.
    let co: i32 = ev_cos(cdeg);
    let si: i32 = ev_sin(cdeg);
    let mut li: i32 = 0;
    let mut wi: i32 = 0;
    let mut x: i32 = 0;
    let mut j: i32 = 0;
    let mut y: i32 = 0;
    let mut dy: i32 = 0;
    let mut on: i32 = 0;
    while li < 8 {
        wi = 0;
        while wi < 10 {
            x = 0;
            while x < 70 {
                on = 1;
                if (x >= 32) && (x < 36) {
                    on = 0;
                }
                if on == 1 {
                    dy = (((((20 + (wi * 90)) + x) as i64) * (si as i64)) / (co as i64)) as i32;
                    j = 0;
                    while j < 14 {
                        y = ((60 + (li * 70)) - dy) + j;
                        if y >= 0 {
                            if y < crate::port::bitmap_h(b) {
                                nt_rect(b, (20 + (wi * 90)) + x, y, ((20 + (wi * 90)) + x) + 1, y + 1, ink, ink, ink);
                            }
                        }
                        j += 1;
                    }
                }
                x += 1;
            }
            wi += 1;
        }
        li += 1;
    }
    return 0;
}
pub(crate) fn nt_skew_of(cdeg: i32) -> i32 {
    let b: &crate::port::Bitmap = &crate::port::bitmap_new(1000, 700, 1);
    let pts: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let prof: &mut crate::port::Cells = &mut crate::port::Cells::new();
    nt_text_lines(b, cdeg, 255);
    return nm_deskew(b, pts, prof);
}
pub(crate) fn nt_near(got: i32, want: i32, tol: i32) -> i32 {
    let mut d: i32 = got - want;
    if d < 0 {
        d = 0 - d;
    }
    if d <= tol {
        return 1;
    }
    return 0;
}
